42	// handleValidateConfiguration validates a configuration document without
43	// creating or persisting anything.
44	func handleValidateConfiguration(w http.ResponseWriter, r *http.Request) {
45		w.Header().Set("Content-Type", "application/json; charset=utf-8")
46		if r.Method != http.MethodPost {
47			w.Header().Set("Allow", http.MethodPost)
48			w.WriteHeader(http.StatusMethodNotAllowed)
49			_ = json.NewEncoder(w).Encode(map[string]any{
50				"error": map[string]string{"code": "method_not_allowed"},
51			})
52			return
53		}
54	
55		doc, ok := decodeConfigurationBody(w, r)
56		if !ok {
57			return
58		}
59	
60		errs := validateConfiguration(doc)
61		sortValidationErrors(errs)
62		if len(errs) == 0 {
63			writeValidation(w, http.StatusOK, nil)
64			return
65		}
66		writeValidation(w, http.StatusUnprocessableEntity, errs)
67	}
68	
69	// decodeConfigurationBody reads the single JSON value expected from a
70	// configuration request body. It writes the shared 400 invalid_json response
71	// and returns ok=false when the body is empty, malformed, or trailing data.
72	func decodeConfigurationBody(w http.ResponseWriter, r *http.Request) (any, bool) {
73		dec := json.NewDecoder(r.Body)
74		dec.UseNumber()
75		var doc any
76		if err := dec.Decode(&doc); err != nil {
77			writeValidation(w, http.StatusBadRequest, []validationError{{
78				Code:    codeInvalidJSON,
79				Message: "request body is empty or is not valid JSON",
80				Path:    "",
81			}})
82			return nil, false
83		}
84		var trailing any
85		if err := dec.Decode(&trailing); err != io.EOF {
86			writeValidation(w, http.StatusBadRequest, []validationError{{
87				Code:    codeInvalidJSON,
88				Message: "request body must contain exactly one JSON value",
89				Path:    "",
90			}})
91			return nil, false
92		}
93		return doc, true
94	}
95	
96	// sortValidationErrors orders findings by JSON Pointer path, then by code.
97	func sortValidationErrors(errs []validationError) {
98		sort.SliceStable(errs, func(i, j int) bool {
99			if errs[i].Path != errs[j].Path {
100				return errs[i].Path < errs[j].Path
101			}
102			return errs[i].Code < errs[j].Code
103		})
104	}
105	
106	func writeValidation(w http.ResponseWriter, status int, errs []validationError) {
107		if errs == nil {
108			errs = []validationError{}
109		}
110		w.WriteHeader(status)
111		_ = json.NewEncoder(w).Encode(validateResponse{Valid: len(errs) == 0, Errors: errs})
112	}
113	
114	// pointerEscape escapes a single JSON Pointer path segment per RFC 6901.
115	func pointerEscape(s string) string {
116		s = strings.ReplaceAll(s, "~", "~0")
117		return strings.ReplaceAll(s, "/", "~1")
118	}
119	
120	// validateConfiguration checks a decoded document and returns every
121	// independently determinable problem, in discovery order.
122	func validateConfiguration(doc any) []validationError {
123		var errs []validationError
124		add := func(code, message, path string) {
125			errs = append(errs, validationError{Code: code, Message: message, Path: path})
126		}
127	
128		root, ok := doc.(map[string]any)
129		if !ok {
130			add(codeInvalidDocument, "document must be a JSON object", "")
131			return errs
132		}
133		for key := range root {
134			if key != "resourceTypes" && key != "resources" {
135				add(codeInvalidDocument, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
136			}
137		}
138	
139		typesRaw, hasTypes := root["resourceTypes"]
140		if !hasTypes {
141			add(codeInvalidDocument, `missing required field "resourceTypes"`, "")
142		}
143		resourcesRaw, hasResources := root["resources"]
144		if !hasResources {
145			add(codeInvalidDocument, `missing required field "resources"`, "")
146		}
147	
148		var typeEntries []any
149		if hasTypes {
150			arr, ok := typesRaw.([]any)
151			if !ok {
152				add(codeInvalidDocument, `"resourceTypes" must be an array`, "/resourceTypes")
153			} else {
154				typeEntries = arr
155			}
156		}
157		var resourceEntries []any
158		if hasResources {
159			arr, ok := resourcesRaw.([]any)
160			if !ok {
161				add(codeInvalidDocument, `"resources" must be an array`, "/resources")
162			} else {
163				resourceEntries = arr
164			}
165		}
166	
167		// declared holds every non-empty type name seen, even when its entry is
168		// invalid or a duplicate; usable holds only names with a valid, unique
169		// schema. Resources referencing a declared-but-unusable name are spared
170		// property-level errors.
171		declared := map[string]bool{}
172		usable := map[string]any{}
173		for i, entry := range typeEntries {
174			entryPath := fmt.Sprintf("/resourceTypes/%d", i)
175			obj, ok := entry.(map[string]any)
176			if !ok {
177				add(codeInvalidDocument, "resource type entry must be an object", entryPath)
178				continue
179			}
180			name, nameValid := identifierField(obj, "name", entryPath, add)
181			schemaRaw, hasSchema := obj["schema"]
182			schemaValid := false
183			if !hasSchema {
184				add(codeInvalidDocument, `missing required field "schema"`, entryPath)
185			} else {
186				before := len(errs)
187				validateSchema(schemaRaw, entryPath+"/schema", add)
188				schemaValid = len(errs) == before
189			}
190			if !nameValid {
191				continue
192			}
193			if declared[name] {
194				add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource type name %q", name), entryPath+"/name")
195				delete(usable, name)
196				continue
197			}
198			declared[name] = true
199			if schemaValid {
200				usable[name] = schemaRaw
201			}
202		}
203	
204		seenAddresses := map[string]bool{}
205		for i, entry := range resourceEntries {
206			entryPath := fmt.Sprintf("/resources/%d", i)
207			obj, ok := entry.(map[string]any)
208			if !ok {
209				add(codeInvalidDocument, "resource entry must be an object", entryPath)
210				continue
211			}
212			if address, ok := identifierField(obj, "address", entryPath, add); ok {
213				if seenAddresses[address] {
214					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
215				} else {
216					seenAddresses[address] = true
217				}
218			}
219	
220			var schema any
221			schemaUsable := false
222			typeRaw, hasType := obj["type"]
223			typeName, typeIsString := typeRaw.(string)
224			switch {
225			case !hasType:
226				add(codeInvalidDocument, `missing required field "type"`, entryPath)
227			case !typeIsString:
228				add(codeInvalidDocument, `"type" must be a string`, entryPath+"/type")
229			case typeName == "":
230				add(codeInvalidDocument, `"type" must not be empty`, entryPath+"/type")
231			case !declared[typeName]:
232				add(codeUnknownResourceType, fmt.Sprintf("unknown resource type %q", typeName), entryPath+"/type")
233			default:
234				if s, ok := usable[typeName]; ok {
235					schema, schemaUsable = s, true
236				}
237			}
238	
239			propsRaw, hasProps := obj["properties"]
240			if !hasProps {
241				add(codeInvalidDocument, `missing required field "properties"`, entryPath)
242				continue
243			}
244			props, ok := propsRaw.(map[string]any)
245			if !ok {
246				add(codeInvalidDocument, `"properties" must be an object`, entryPath+"/properties")
247				continue
248			}
249			if schemaUsable {
250				validateValue(props, schema, entryPath+"/properties", add)
251			}
252		}
253	
254		return errs
255	}
256	
257	// identifierField extracts a required non-empty string field, reporting
258	// invalid_document for a missing, non-string, or empty value.
259	func identifierField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
260		raw, ok := obj[field]
261		if !ok {
262			add(codeInvalidDocument, fmt.Sprintf("missing required field %q", field), path)
263			return "", false
264		}
265		s, ok := raw.(string)
266		if !ok {
267			add(codeInvalidDocument, fmt.Sprintf("%q must be a string", field), path+"/"+field)
268			return "", false
269		}
270		if s == "" {
271			add(codeInvalidDocument, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
272			return "", false
273		}
274		return s, true
275	}
276	
277	// validateSchema checks the structural legality of a schema, recursing into
278	// array items and object properties.
279	func validateSchema(schema any, path string, add func(code, message, path string)) {
280		obj, ok := schema.(map[string]any)
281		if !ok {
282			add(codeInvalidDocument, "schema must be an object", path)
283			return
284		}
285		typeRaw, hasType := obj["type"]
286		typeName, isString := typeRaw.(string)
287		if !hasType {
288			add(codeInvalidDocument, `missing required field "type"`, path)
289			return
290		}
291		if !isString {
292			add(codeInvalidDocument, `"type" must be a string`, path+"/type")
293			return
294		}
295		switch typeName {
296		case "string", "integer", "number", "boolean":
297		case "array":
298			items, has := obj["items"]
299			if !has {
300				add(codeInvalidDocument, `array schema requires "items"`, path)
301				return
302			}
303			validateSchema(items, path+"/items", add)
304		case "object":
305			if propsRaw, has := obj["properties"]; has {
306				props, ok := propsRaw.(map[string]any)
307				if !ok {
308					add(codeInvalidDocument, `"properties" must be an object`, path+"/properties")
309				} else {
310					names := make([]string, 0, len(props))
311					for name := range props {
312						names = append(names, name)
313					}
314					sort.Strings(names)
315					for _, name := range names {
316						validateSchema(props[name], path+"/properties/"+pointerEscape(name), add)
317					}
318				}
319			}
320			if reqRaw, has := obj["required"]; has {
321				req, ok := reqRaw.([]any)
322				if !ok {
323					add(codeInvalidDocument, `"required" must be an array of strings`, path+"/required")
324				} else {
325					for j, entry := range req {
326						if _, ok := entry.(string); !ok {
327							add(codeInvalidDocument, `"required" entries must be strings`, fmt.Sprintf("%s/required/%d", path, j))
328						}
329					}
330				}
331			}
332			if apRaw, has := obj["additionalProperties"]; has {
333				if _, ok := apRaw.(bool); !ok {
334					add(codeInvalidDocument, `"additionalProperties" must be a boolean`, path+"/additionalProperties")
335				}
336			}
337		default:
338			add(codeInvalidDocument, fmt.Sprintf("unknown schema type %q", typeName), path+"/type")
339		}
340	}
341	
342	// validateValue checks a value against an already-validated schema.
343	func validateValue(value, schema any, path string, add func(code, message, path string)) {
344		obj, ok := schema.(map[string]any)
345		if !ok {
346			return
347		}
348		typeName, _ := obj["type"].(string)
349		switch typeName {
350		case "string":
351			if _, ok := value.(string); !ok {
352				add(codeTypeMismatch, fmt.Sprintf("expected string, got %s", jsonTypeName(value)), path)
353			}
354		case "boolean":
355			if _, ok := value.(bool); !ok {
356				add(codeTypeMismatch, fmt.Sprintf("expected boolean, got %s", jsonTypeName(value)), path)
357			}
358		case "integer":
359			n, ok := value.(json.Number)
360			if !ok || !isJSONInteger(n) {
361				add(codeTypeMismatch, fmt.Sprintf("expected integer, got %s", jsonTypeName(value)), path)
362			}
363		case "number":
364			if _, ok := value.(json.Number); !ok {
365				add(codeTypeMismatch, fmt.Sprintf("expected number, got %s", jsonTypeName(value)), path)
366			}
367		case "array":
368			arr, ok := value.([]any)
369			if !ok {
370				add(codeTypeMismatch, fmt.Sprintf("expected array, got %s", jsonTypeName(value)), path)
371				return
372			}
373			items := obj["items"]
374			for i, el := range arr {
375				validateValue(el, items, fmt.Sprintf("%s/%d", path, i), add)
376			}
377		case "object":
378			rec, ok := value.(map[string]any)
379			if !ok {
380				add(codeTypeMismatch, fmt.Sprintf("expected object, got %s", jsonTypeName(value)), path)
381				return
382			}
383			props, _ := obj["properties"].(map[string]any)
384			additional := false
385			if ap, ok := obj["additionalProperties"].(bool); ok {
386				additional = ap
387			}
388			seen := map[string]bool{}
389			if reqRaw, ok := obj["required"].([]any); ok {
390				for _, entry := range reqRaw {
391					name, ok := entry.(string)
392					if !ok || seen[name] {
393						continue
394					}
395					seen[name] = true
396					if _, present := rec[name]; !present {
397						add(codeMissingRequiredProperty, fmt.Sprintf("missing required property %q", name), path)
398					}
399				}
400			}
401			names := make([]string, 0, len(rec))
402			for name := range rec {
403				names = append(names, name)
404			}
405			sort.Strings(names)
406			for _, name := range names {
407				childPath := path + "/" + pointerEscape(name)
408				if sub, declared := props[name]; declared {
409					validateValue(rec[name], sub, childPath, add)
410				} else if !additional {
411					add(codeUnexpectedProperty, fmt.Sprintf("unexpected property %q", name), childPath)
412				}
413			}
414		}
415	}
416	
417	// isJSONInteger reports whether a JSON number literal denotes an integer.
418	// Whole-valued forms such as 1.0 or 1e2 count as integers; fractions do not.
419	func isJSONInteger(n json.Number) bool {
420		s := n.String()
421		if _, err := strconv.ParseInt(s, 10, 64); err == nil {
422			return true
423		}
424		f, err := strconv.ParseFloat(s, 64)
425		if err != nil {
426			return false
427		}
428		return !math.IsInf(f, 0) && f == math.Trunc(f)
429	}
430	
431	func jsonTypeName(v any) string {
432		switch v.(type) {
433		case nil:
434			return "null"
435		case bool:
436			return "boolean"
437		case json.Number:
438			return "number"
439		case string:
440			return "string"
441		case []any:
442			return "array"
443		case map[string]any:
444			return "object"
445		default:
446			return "value"
447		}
448	}
