11	// Error code reported when the plan request envelope or the prior state
12	// document is structurally invalid.
13	const codeInvalidPlanRequest = "invalid_plan_request"
14	
15	// planSnapshot is the normalized view of one resource at one side of a
16	// change: before for the prior state, after for the configuration. It is an
17	// alias of the exported Snapshot handed to Provider implementations so that
18	// the read-only plan endpoint and the apply endpoint share one shape.
19	type planSnapshot = Snapshot
