39		Errors  []validationError `json:"errors"`
40		Changes []planChange      `json:"changes"`
41		Summary planSummary       `json:"summary"`
42	}
43	
44	// planResource is the plan-relevant view of one resource, extracted from an
45	// already-validated configuration or prior state document.
46	type planResource struct {
47		address    string
48		typ        string
49		properties map[string]any
50		dependsOn  []string
51	}
52	
53	// handlePlanConfiguration computes the diff between a desired configuration
54	// and a prior state. It only computes the plan; nothing is applied or
55	// persisted.
56	func handlePlan(w http.ResponseWriter, r *http.Request) {
57		w.Header().Set("Content-Type", "application/json; charset=utf-8")
58		if r.Method != http.MethodPost {
59			rejectMethodNotAllowed(w)
60			return
61		}
62	
63		changes, summary, _, ok := preparePlan(w, r)
64		if !ok {
65			return
66		}
67	
68		w.WriteHeader(http.StatusOK)
69		_ = json.NewEncoder(w).Encode(planResponse{
70			Valid:   true,
71			Errors:  []validationError{},
72			Changes: changes,
73			Summary: summary,
74		})
75	}
76	
77	// preparePlan runs the request through the same pipeline the read-only plan
78	// endpoint uses: decode the body, validate the envelope, configuration,
79	// dependencies and prior state, then compute the ordered diff. On any client
80	// failure it writes the 400/422 response itself and returns ok=false, so the
81	// caller never invokes a Provider for an invalid request. On success it also
82	// returns the validated prior-state resources, used to seed the resulting
83	// state of an apply run.
84	func preparePlan(w http.ResponseWriter, r *http.Request) (changes []planChange, summary planSummary, stateResources []planResource, ok bool) {
85		doc, ok := decodeConfigurationBody(w, r)
86		if !ok {
87			return nil, planSummary{}, nil, false
88		}
89	
90		configRaw, stateRaw, ok := checkPlanEnvelope(w, doc)
91		if !ok {
92			return nil, planSummary{}, nil, false
93		}
94	
95		// Configuration and prior state are validated independently; their
96		// findings are merged and sorted together. Configuration findings keep
97		// their codes and gain a /configuration path prefix.
98		var errs []validationError
99		var configResources []planResource
100		var configOrder []string
101		if baseErrs := validateConfiguration(configRaw); len(baseErrs) != 0 {
102			errs = appendPrefixedErrors(errs, baseErrs, "/configuration")
103		} else if order, depErrs := orderConfiguration(configRaw); len(depErrs) != 0 {
104			errs = appendPrefixedErrors(errs, depErrs, "/configuration")
105		} else {
106			configResources = configurationResources(configRaw)
107			configOrder = order
108		}
109	
110		stateResources, stateOrder, stateErrs := checkPriorState(stateRaw)
111		errs = append(errs, stateErrs...)
112	
113		if len(errs) != 0 {
114			sortValidationErrors(errs)
115			writeValidation(w, http.StatusUnprocessableEntity, errs)
116			return nil, planSummary{}, nil, false
117		}
118	
119		changes, summary = computePlan(configResources, configOrder, stateResources, stateOrder)
120		return changes, summary, stateResources, true
121	}
122	
123	// rejectMethodNotAllowed writes the shared 405 response for the POST-only
124	// planning and apply endpoints: Allow: POST and a method_not_allowed code.
125	func rejectMethodNotAllowed(w http.ResponseWriter) {
126		w.Header().Set("Allow", http.MethodPost)
127		w.WriteHeader(http.StatusMethodNotAllowed)
128		_ = json.NewEncoder(w).Encode(map[string]any{
129			"error": map[string]string{"code": "method_not_allowed"},
130		})
131	}
132	
133	// checkPlanEnvelope validates the request envelope: a JSON object holding
134	// exactly the configuration and priorState fields. On failure it writes the
135	// 422 response and returns ok=false.
136	func checkPlanEnvelope(w http.ResponseWriter, doc any) (configuration, priorState any, ok bool) {
137		var errs []validationError
138		add := func(code, message, path string) {
139			errs = append(errs, validationError{Code: code, Message: message, Path: path})
140		}
141	
142		root, isObject := doc.(map[string]any)
143		if !isObject {
144			add(codeInvalidPlanRequest, "request body must be a JSON object", "")
145		} else {
146			for key := range root {
147				if key != "configuration" && key != "priorState" {
148					add(codeInvalidPlanRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
149				}
150			}
151			var hasConfig, hasState bool
152			configuration, hasConfig = root["configuration"]
153			priorState, hasState = root["priorState"]
154			if !hasConfig {
155				add(codeInvalidPlanRequest, `missing required field "configuration"`, "")
156			}
157			if !hasState {
158				add(codeInvalidPlanRequest, `missing required field "priorState"`, "")
159			}
160		}
161	
162		if len(errs) != 0 {
163			sortValidationErrors(errs)
164			writeValidation(w, http.StatusUnprocessableEntity, errs)
165			return nil, nil, false
166		}
167		return configuration, priorState, true
168	}
169	
170	// appendPrefixedErrors appends errs to dst with every path rooted at prefix,
171	// so findings from an embedded document point into the request envelope.
172	func appendPrefixedErrors(dst []validationError, errs []validationError, prefix string) []validationError {
173		for _, e := range errs {
174			e.Path = prefix + e.Path
175			dst = append(dst, e)
176		}
177		return dst
178	}
179	
180	// configurationResources extracts the plan-relevant view of an
181	// already-validated configuration document.
182	func configurationResources(doc any) []planResource {
183		root := doc.(map[string]any)
184		entries := root["resources"].([]any)
185		resources := make([]planResource, 0, len(entries))
186		for _, entry := range entries {
187			obj := entry.(map[string]any)
188			var deps []string
189			if raw, ok := obj["dependsOn"].([]any); ok {
190				for _, el := range raw {
191					deps = append(deps, el.(string))
192				}
193			}
194			resources = append(resources, planResource{
195				address:    obj["address"].(string),
196				typ:        obj["type"].(string),
197				properties: obj["properties"].(map[string]any),
198				dependsOn:  deps,
199			})
200		}
201		return resources
202	}
203	
204	// checkPriorState validates the priorState document: an object with a
205	// resources array whose entries have a non-empty unique address, a non-empty
206	// type, a properties object, and an optional dependsOn. State types are not
207	// checked against the configuration's resource types. Shape problems are
208	// reported as invalid_plan_request and suppress dependency interpretation;
209	// dependency problems reuse the configuration dependency codes.
210	func checkPriorState(raw any) ([]planResource, []string, []validationError) {
211		const base = "/priorState"
212		var errs []validationError
213		add := func(code, message, path string) {
214			errs = append(errs, validationError{Code: code, Message: message, Path: path})
215		}
216	
217		obj, ok := raw.(map[string]any)
218		if !ok {
219			add(codeInvalidPlanRequest, `"priorState" must be an object`, base)
220			return nil, nil, errs
221		}
222		resourcesRaw, hasResources := obj["resources"]
223		if !hasResources {
224			add(codeInvalidPlanRequest, `missing required field "resources"`, base)
225			return nil, nil, errs
226		}
227		entries, ok := resourcesRaw.([]any)
228		if !ok {
229			add(codeInvalidPlanRequest, `"resources" must be an array`, base+"/resources")
230			return nil, nil, errs
231		}
232	
233		resources := make([]planResource, len(entries))
234		seenAddresses := map[string]bool{}
235		for i, entry := range entries {
236			entryPath := fmt.Sprintf("%s/resources/%d", base, i)
237			entryObj, ok := entry.(map[string]any)
238			if !ok {
239				add(codeInvalidPlanRequest, "state resource entry must be an object", entryPath)
240				continue
241			}
242			address, addressOK := planStringField(entryObj, "address", entryPath, add)
243			if addressOK {
244				if seenAddresses[address] {
245					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
246					addressOK = false
247				} else {
248					seenAddresses[address] = true
249				}
250			}
251			typ, typeOK := planStringField(entryObj, "type", entryPath, add)
252			propsRaw, hasProps := entryObj["properties"]
253			props, propsOK := propsRaw.(map[string]any)
254			switch {
255			case !hasProps:
256				add(codeInvalidPlanRequest, `missing required field "properties"`, entryPath)
257			case !propsOK:
258				add(codeInvalidPlanRequest, `"properties" must be an object`, entryPath+"/properties")
259			}
260			if !addressOK || !typeOK || !hasProps || !propsOK {
261				continue
262			}
263			resources[i] = planResource{address: address, typ: typ, properties: props}
264		}
265		if len(errs) != 0 {
266			return nil, nil, errs
267		}
268	
269		addresses := make([]string, len(entries))
270		for i, resource := range resources {
271			addresses[i] = resource.address
272		}
273		dependsOn, order, depErrs := resolveDependencies(entries, addresses, base+"/resources")
274		if len(depErrs) != 0 {
275			return nil, nil, depErrs
276		}
277		for i := range resources {
278			resources[i].dependsOn = dependsOn[i]
279		}
280		return resources, order, nil
281	}
282	
283	// planStringField extracts a required non-empty string field of a prior
284	// state entry, reporting invalid_plan_request otherwise.
285	func planStringField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
286		raw, ok := obj[field]
287		if !ok {
288			add(codeInvalidPlanRequest, fmt.Sprintf("missing required field %q", field), path)
289			return "", false
290		}
291		s, ok := raw.(string)
292		if !ok {
293			add(codeInvalidPlanRequest, fmt.Sprintf("%q must be a string", field), path+"/"+field)
294			return "", false
295		}
296		if s == "" {
297			add(codeInvalidPlanRequest, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
298			return "", false
299		}
300		return s, true
301	}
302	
303	// computePlan aligns desired and prior resources by address. Deletes are
304	// listed in the reverse of the prior state's topological order; creates and
305	// updates follow the configuration's deterministic topological order.
306	// Resources equal on both sides are counted as noop and produce no change.
307	func computePlan(configResources []planResource, configOrder []string, stateResources []planResource, stateOrder []string) ([]planChange, planSummary) {
308		configByAddress := make(map[string]planResource, len(configResources))
309		for _, resource := range configResources {
310			configByAddress[resource.address] = resource
311		}
312		stateByAddress := make(map[string]planResource, len(stateResources))
313		for _, resource := range stateResources {
314			stateByAddress[resource.address] = resource
315		}
316	
317		actions := make(map[string]string, len(configResources)+len(stateResources))
318		var summary planSummary
319		for _, resource := range configResources {
320			prior, existed := stateByAddress[resource.address]
321			switch {
322			case !existed:
323				actions[resource.address] = "create"
324				summary.Create++
325			case resourceEqual(resource, prior):
326				summary.Noop++
327			default:
328				actions[resource.address] = "update"
329				summary.Update++
330			}
331		}
332		for _, resource := range stateResources {
333			if _, desired := configByAddress[resource.address]; !desired {
334				actions[resource.address] = "delete"
335				summary.Delete++
336			}
337		}
338	
339		changes := make([]planChange, 0, len(actions))
340		for i := len(stateOrder) - 1; i >= 0; i-- {
341			address := stateOrder[i]
342			if actions[address] != "delete" {
343				continue
344			}
345			before := snapshotOf(stateByAddress[address])
346			changes = append(changes, planChange{Address: address, Action: "delete", Before: &before})
347		}
348		for _, address := range configOrder {
349			action := actions[address]
350			if action != "create" && action != "update" {
351				continue
352			}
353			after := snapshotOf(configByAddress[address])
354			change := planChange{Address: address, Action: action, After: &after}
355			if action == "update" {
356				before := snapshotOf(stateByAddress[address])
357				change.Before = &before
358			}
359			changes = append(changes, change)
360		}
361		return changes, summary
362	}
363	
364	// snapshotOf renders a resource as a change snapshot with its dependencies
365	// normalized to ascending order.
366	func snapshotOf(resource planResource) planSnapshot {
367		deps := make([]string, len(resource.dependsOn))
368		copy(deps, resource.dependsOn)
369		sort.Strings(deps)
370		return planSnapshot{
371			Type:       resource.typ,
372			Properties: resource.properties,
373			DependsOn:  deps,
374		}
375	}
376	
377	// resourceEqual reports whether a desired and a prior resource are
378	// equivalent: same type, deeply equal properties, and equal dependency sets.
379	func resourceEqual(desired, prior planResource) bool {
380		if desired.typ != prior.typ {
381			return false
382		}
383		if !jsonValueEqual(desired.properties, prior.properties) {
384			return false
385		}
386		return stringSetEqual(desired.dependsOn, prior.dependsOn)
387	}
388	
389	// jsonValueEqual compares two decoded JSON values. Object key order is
390	// ignored, numbers compare by numeric value, and arrays are ordered.
391	func jsonValueEqual(a, b any) bool {
392		switch av := a.(type) {
393		case json.Number:
394			bv, ok := b.(json.Number)
395			return ok && jsonNumberEqual(av, bv)
396		case map[string]any:
397			bv, ok := b.(map[string]any)
398			if !ok || len(av) != len(bv) {
399				return false
400			}
401			for key, value := range av {
402				other, present := bv[key]
403				if !present || !jsonValueEqual(value, other) {
404					return false
405				}
406			}
407			return true
408		case []any:
409			bv, ok := b.([]any)
410			if !ok || len(av) != len(bv) {
411				return false
412			}
413			for i := range av {
414				if !jsonValueEqual(av[i], bv[i]) {
415					return false
416				}
417			}
418			return true
419		default:
420			return a == b
421		}
422	}
423	
424	// jsonNumberEqual compares two JSON number literals by numeric value, so
425	// 1, 1.0, and 1e0 are all equal.
426	func jsonNumberEqual(a, b json.Number) bool {
427		ra, okA := new(big.Rat).SetString(a.String())
428		rb, okB := new(big.Rat).SetString(b.String())
429		if okA && okB {
430			return ra.Cmp(rb) == 0
431		}
432		return a.String() == b.String()
433	}
434	
435	// stringSetEqual compares two duplicate-free string lists as sets.
436	func stringSetEqual(a, b []string) bool {
437		if len(a) != len(b) {
438			return false
439		}
440		counts := make(map[string]int, len(a))
441		for _, s := range a {
442			counts[s]++
443		}
444		for _, s := range b {
445			counts[s]--
446			if counts[s] < 0 {
447				return false
448			}
449		}
450		return true
451	}
452

